using Ordering.Legacy;

namespace Ordering;

public interface ILabelRenderer
{
    string Render(string orderReference, string service);
}

public sealed class CurrentLabelRenderer : ILabelRenderer
{
    public string Render(string orderReference, string service)
    {
        return LabelApiV2.Render(orderReference, service);
    }
}

/// <summary>Produces dispatch labels for an order.</summary>
public sealed class LabelPrinter
{
    private readonly ILabelRenderer _renderer;

    public LabelPrinter(ILabelRenderer renderer) => _renderer = renderer;

    public string Print(Order order, string service)
    {
        ArgumentNullException.ThrowIfNull(order);
        return _renderer.Render(order.Reference, service);
    }
}
